const FAVICON_PNG = "";
const STRONGER_SELF_ICON = "";
const FAVICON_SVG = "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 128 128\">\n<rect width=\"128\" height=\"128\" fill=\"#5b328f\"/>\n<image href=\"data:image/png;base64,\" x=\"0\" y=\"0\" width=\"128\" height=\"128\">\n<animate attributeName=\"y\" values=\"0;-2;0\" dur=\"2.6s\" repeatCount=\"indefinite\"/>\n</image></svg>";
const RENDERED_PAGE_HTML = PAGE_HTML;
const PWA_MANIFEST = "{\n  \"name\": \"Abhyudaya’s Best Life\",\n  \"short_name\": \"Best Life\",\n  \"description\": \"Abhyudaya’s personal fitness journal and training journey.\",\n  \"id\": \"/\",\n  \"start_url\": \"/\",\n  \"scope\": \"/\",\n  \"display\": \"standalone\",\n  \"orientation\": \"any\",\n  \"background_color\": \"#17202b\",\n  \"theme_color\": \"#17202b\",\n  \"icons\": [\n    {\n      \"src\": \"/pwa-icon-192.png\",\n      \"sizes\": \"192x192\",\n      \"type\": \"image/png\",\n      \"purpose\": \"any\"\n    },\n    {\n      \"src\": \"/pwa-icon-512.png\",\n      \"sizes\": \"512x512\",\n      \"type\": \"image/png\",\n      \"purpose\": \"any\"\n    },\n    {\n      \"src\": \"/pwa-icon-512.png\",\n      \"sizes\": \"512x512\",\n      \"type\": \"image/png\",\n      \"purpose\": \"maskable\"\n    }\n  ]\n}\n";
const SERVICE_WORKER = "const CACHE_NAME = 'best-life-shell-v1';\nconst STATIC_ASSETS = [\n  '/manifest.webmanifest',\n  '/pwa-icon-192.png',\n  '/pwa-icon-512.png',\n  '/apple-touch-icon.png',\n  '/stronger-self-icon.webp'\n];\n\nself.addEventListener('install', event => {\n  event.waitUntil(caches.open(CACHE_NAME).then(cache => cache.addAll(STATIC_ASSETS)));\n  self.skipWaiting();\n});\n\nself.addEventListener('activate', event => {\n  event.waitUntil(\n    caches.keys().then(keys => Promise.all(keys.filter(key => key !== CACHE_NAME).map(key => caches.delete(key))))\n  );\n  self.clients.claim();\n});\n\nself.addEventListener('fetch', event => {\n  const request = event.request;\n  const url = new URL(request.url);\n  if (request.method !== 'GET' || url.origin !== self.location.origin || url.pathname.startsWith('/api/')) return;\n\n  if (request.mode === 'navigate') {\n    event.respondWith(\n      fetch(request).then(response => {\n        if (response.ok) caches.open(CACHE_NAME).then(cache => cache.put(request, response.clone()));\n        return response;\n      }).catch(async () => (await caches.match(request)) || (await caches.match('/')) || Response.error())\n    );\n    return;\n  }\n\n  event.respondWith(caches.match(request).then(cached => cached || fetch(request).then(response => {\n    if (response.ok) caches.open(CACHE_NAME).then(cache => cache.put(request, response.clone()));\n    return response;\n  })));\n});\n";
const PWA_ICON_192 = "";
const PWA_ICON_512 = "";
const APPLE_TOUCH_ICON = "";
const emptyRecord = () => ({ version: 2, planRevision: PLAN_REVISION, checked: {}, rewards: { claimed: {}, custom: {}, locked: {} }, notes: {}, weekly: {}, measurements: [], shownMilestones: {}, nutrition: { adherence: {} } });
const json = (value, status = 200) => new Response(JSON.stringify(value), {
  status,
  headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store", "x-content-type-options": "nosniff" },
});
const object = value => value && typeof value === "object" && !Array.isArray(value);
function validRecord(record) {
  if (!object(record) || record.planRevision !== PLAN_REVISION || record.version !== 2 || !object(record.checked) || !object(record.rewards) ||
      !object(record.rewards.claimed) || !object(record.rewards.custom) || !object(record.rewards.locked) ||
      !object(record.notes) || !object(record.weekly) || !Array.isArray(record.measurements) ||
      !object(record.nutrition) || !object(record.nutrition.adherence)) return false;
  const phase = "(?:launchpad|cardio|circuit|gladiator-[0-5]|byow-[0-7])";
  const task = new RegExp("^" + phase + "-\\d{1,2}-[01]$");
  const week = new RegExp("^" + phase + "-\\d{1,2}$");
  const reward = /^(?:genai|planning|cardio|circuit|week10|block[0-5])$/;
  const block = /^block[0-5]$/;
  const entries = Object.entries;
  if (entries(record.checked).length > 1000 || !entries(record.checked).every(([k,v]) => task.test(k) && v === true)) return false;
  if (entries(record.notes).length > 80 || !entries(record.notes).every(([k,v]) => week.test(k) && typeof v === "string" && v.length <= 350000)) return false;
  if (entries(record.rewards.claimed).length > 11 || !entries(record.rewards.claimed).every(([k,v]) => reward.test(k) && v === true)) return false;
  if (entries(record.rewards.custom).length > 6 || !entries(record.rewards.custom).every(([k,v]) => block.test(k) && typeof v === "string" && v.length <= 300)) return false;
  if (entries(record.rewards.locked).length > 6 || !entries(record.rewards.locked).every(([k,v]) => block.test(k) && v === true && !!record.rewards.custom[k]?.trim())) return false;
  if (entries(record.weekly).length > 80 || !entries(record.weekly).every(([k,v]) => week.test(k) && object(v) &&
      (v.weight === null || (typeof v.weight === "number" && v.weight >= 30 && v.weight <= 300)) &&
      (v.bodyFat === null || (typeof v.bodyFat === "number" && v.bodyFat >= 3 && v.bodyFat <= 70)))) return false;
  const fields = new Set(["chest","shoulders","waistBelly","waistHandles","hips","bicepsRight","bicepsLeft","forearmRight","forearmLeft","thigh","calves","neck","weight","bodyFat"]);
  if (record.measurements.length > 200) return false;
  if (entries(record.nutrition.adherence).length > 730 || !entries(record.nutrition.adherence).every(([k,v]) => /^\d{4}-\d{2}-\d{2}$/.test(k) && v === true)) return false;
  return record.measurements.every(row => object(row) && /^\d{4}-\d{2}-\d{2}$/.test(row.date) &&
    entries(row).every(([k,v]) => k === "date" || (fields.has(k) && typeof v === "number" && Number.isFinite(v) && v >= 0 && v <= 300)));
}
export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if(url.pathname==="/barcode-reader.js") return new Response(BARCODE_READER_JS,{headers:{"content-type":"text/javascript; charset=utf-8","cache-control":"public, max-age=86400","x-content-type-options":"nosniff"}});
    if(url.pathname.startsWith("/api/nutrition/")) return handleNutrition(request,env);
    if (url.pathname === "/manifest.webmanifest") return new Response(PWA_MANIFEST, {headers: {"content-type":"application/manifest+json; charset=utf-8","cache-control":"public, max-age=3600","x-content-type-options":"nosniff"}});
    if (url.pathname === "/sw.js") return new Response(SERVICE_WORKER, {headers: {"content-type":"text/javascript; charset=utf-8","cache-control":"no-cache","service-worker-allowed":"/","x-content-type-options":"nosniff"}});
    if (url.pathname === "/pwa-icon-192.png") return new Response(Uint8Array.from(atob(PWA_ICON_192), c=>c.charCodeAt(0)), {headers: {"content-type":"image/png","cache-control":"public, max-age=86400"}});
    if (url.pathname === "/pwa-icon-512.png") return new Response(Uint8Array.from(atob(PWA_ICON_512), c=>c.charCodeAt(0)), {headers: {"content-type":"image/png","cache-control":"public, max-age=86400"}});
    if (url.pathname === "/apple-touch-icon.png") return new Response(Uint8Array.from(atob(APPLE_TOUCH_ICON), c=>c.charCodeAt(0)), {headers: {"content-type":"image/png","cache-control":"public, max-age=86400"}});
    if (url.pathname === "/favicon.svg") return new Response(FAVICON_SVG, {headers: {"content-type":"image/svg+xml; charset=utf-8","cache-control":"public, max-age=86400"}});
    if (url.pathname === "/face-icon.png") return new Response(Uint8Array.from(atob(FAVICON_PNG), c=>c.charCodeAt(0)), {headers: {"content-type":"image/png","cache-control":"public, max-age=86400"}});
    if (url.pathname === "/stronger-self-icon.webp") return new Response(Uint8Array.from(atob(STRONGER_SELF_ICON), c=>c.charCodeAt(0)), {headers: {"content-type":"image/webp","cache-control":"public, max-age=86400"}});
    if (url.pathname === "/api/medical-documents") {
      const userId = request.headers.get("oai-authenticated-user-id");
      if (!userId) return json({ error: "Sign in to manage private files." }, 401);
      if (!env.DB || !env.BUCKET) return json({ error: "Private file storage is unavailable." }, 503);
      try {
        if (request.method === "GET") {
          const rows = await env.DB.prepare("SELECT id, file_name AS fileName, content_type AS contentType, category, size_bytes AS sizeBytes, uploaded_at AS uploadedAt FROM medical_documents WHERE user_id = ? ORDER BY uploaded_at DESC LIMIT 100").bind(userId).all();
          return json({ documents: rows.results || [] });
        }
        if (request.method === "POST") {
          const form = await request.formData(), file = form.get("file"), category = String(form.get("category") || "other");
          if (!(file instanceof File) || !file.name || file.size < 1) return json({ error: "Choose a file to upload." }, 400);
          if (file.size > 15 * 1024 * 1024) return json({ error: "Choose a file smaller than 15 MB." }, 413);
          if (!new Set(["medical","nutrition","ideas","other"]).has(category)) return json({ error: "Invalid data category." }, 400);
          const id = crypto.randomUUID(), safeName = file.name.replace(/[^a-zA-Z0-9._ -]/g, "_").slice(0, 160), objectKey = userId + "/" + id + "/" + safeName, uploadedAt = new Date().toISOString();
          await env.BUCKET.put(objectKey, file.stream(), { httpMetadata: { contentType: file.type || "application/octet-stream" }, customMetadata: { userId, category, originalName: safeName } });
          try {
            await env.DB.prepare("INSERT INTO medical_documents (id, user_id, file_name, content_type, category, object_key, size_bytes, uploaded_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)").bind(id, userId, safeName, file.type || "application/octet-stream", category, objectKey, String(file.size), uploadedAt).run();
          } catch (error) { await env.BUCKET.delete(objectKey); throw error; }
          return json({ ok: true, document: { id, fileName: safeName, category, sizeBytes: String(file.size), uploadedAt } }, 201);
        }
        return json({ error: "Method not allowed." }, 405);
      } catch (error) {
        console.error("Medical document storage error", error);
        return json({ error: "Private file storage is temporarily unavailable." }, 503);
      }
    }
    if (url.pathname === "/api/progress") {
      const userId = request.headers.get("oai-authenticated-user-id");
      if (!userId) return json({ error: "Sign in to save progress across devices." }, 401);
      if (!env.DB) return json({ error: "Progress storage is unavailable." }, 503);
      try {
        if (request.method === "GET") {
          const row = await env.DB.prepare("SELECT record FROM user_progress WHERE user_id = ?").bind(userId).first();
          let record=row ? JSON.parse(row.record) : emptyRecord();
          if(record.planRevision!==PLAN_REVISION){
            record=emptyRecord();
            await env.DB.prepare("UPDATE user_progress SET record = ?, updated_at = ? WHERE user_id = ? AND json_extract(record, '$.planRevision') IS NOT ?").bind(JSON.stringify(record),new Date().toISOString(),userId,PLAN_REVISION).run();
            const current=await env.DB.prepare("SELECT record FROM user_progress WHERE user_id = ?").bind(userId).first();
            if(current)record=JSON.parse(current.record);
          }
          return json({ record, hasSavedRecord: !!row });
        }
        if (request.method === "PUT") {
          const body = await request.text();
          if (body.length > 150000) return json({ error: "Progress record is too large." }, 413);
          let record;
          try { record = JSON.parse(body); } catch { return json({ error: "Invalid progress record." }, 400); }
          if(object(record)&&record.version===2&&record.planRevision!==PLAN_REVISION)return json({ error: "The training plan changed. Reload before saving progress." },409);
          if (!validRecord(record)) return json({ error: "Invalid progress record." }, 400);
          await env.DB.prepare("INSERT INTO user_progress (user_id, record, updated_at) VALUES (?, ?, ?) ON CONFLICT(user_id) DO UPDATE SET record = excluded.record, updated_at = excluded.updated_at")
            .bind(userId, body, new Date().toISOString()).run();
          return json({ ok: true });
        }
        return json({ error: "Method not allowed." }, 405);
      } catch (error) {
        console.error("Progress storage error", error);
        return json({ error: "Progress storage is temporarily unavailable." }, 503);
      }
    }
    if (request.method !== "GET" && request.method !== "HEAD") return new Response("Method not allowed", { status: 405 });
    if (url.pathname === "/" || new Set(["/foundation", "/nutrition", "/body-stats", "/workouts", "/more", "/general-fitness", "/fat-loss", "/strength-size", "/rounds-of-fury", "/juggernaut", "/unit"]).has(url.pathname.replace(/\/$/, "")) || /^\/byow-[1-8]\/?$/.test(url.pathname)) {
      return new Response(RENDERED_PAGE_HTML, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } });
    }
    return new Response("Not found", { status: 404 });
  },
};
